namespace UnityGame.Plugins;    using UnityEngine;using Scripts;// This class listens to events from GameLogic and Networkingpublic class GUI : MonoBehaviour{    public GameObject localCube, remoteCube;    private GameLogic game;    private INetwork network;    private Queue<Action> mainThreadQueue = new Queue<Action>(); // Queue for thread-safe execution        // We can change this in Unity Inspector to switch network types    [SerializeField] private string networkType = "UnityGame.Plugins.MulticastingNetwork";    void Start()    {        game = new GameLogic();        network = CreateNetworkComponent(networkType);        remoteCube = GameObject.Find("CubeA");        localCube = GameObject.Find("CubeB");        remoteCube.transform.position = game.RemoteCubePos;        localCube.transform.position = game.LocalCubePos;                    // Subscribe to events        game.OnLocalCubeMoved += UpdateLocalCubePos;        game.OnRemoteCubeMoved += UpdateRemoteCubePos;        network.OnMessageReceived += HandleNetworkMessage;                    // Start Listening to messages in the network dynamically       _ = network.StartListening();    }    void Update()    {        if (Input.anyKey)        {            if (Input.GetKey(KeyCode.RightArrow)) game.MoveLocalCube(0.1f, 0);            if (Input.GetKey(KeyCode.LeftArrow)) game.MoveLocalCube(-0.1f, 0);            if (Input.GetKey(KeyCode.UpArrow)) game.MoveLocalCube(0, 0.1f);            if (Input.GetKey(KeyCode.DownArrow)) game.MoveLocalCube(0, -0.1f);            if (game.CheckCollision())                Debug.Log("Collision Detected");            // Send message            network.SendMessage($"x={game.LocalCubePos.x},y={game.LocalCubePos.y},z={game.LocalCubePos.z}");                            // Process queue network messages in the main thread            while (mainThreadQueue.Count > 0)            {                mainThreadQueue.Dequeue()?.Invoke();            }        }    }            private void UpdateLocalCubePos(Vector3 newPos)    {        localCube.transform.position = newPos;    }    private void UpdateRemoteCubePos(Vector3 newPos)    {        remoteCube.transform.position = newPos;    }    private void HandleNetworkMessage(string message)    {        Debug.Log("Message Received: " + message);                    string[] parts = message.Split(',');        if (parts.Length == 3)        {            float x = float.Parse(parts[0].Split('=')[1]);            float y = float.Parse(parts[1].Split('=')[1]);            float z = float.Parse(parts[2].Split('=')[1]);                            game.UpdateRemoteCube(new Vector3(x, y, z));        }    }    // Use reflection to dynamically swap network connection between multicasting and websocket at runtime    private INetwork CreateNetworkComponent(string typeName)    {        Type type = Type.GetType(typeName);        if (type != null && typeof(INetwork).IsAssignableFrom(type))        {            return (INetwork)Activator.CreateInstance(type);        }        throw new Exception($"Cannot create network component of type {typeName}");    }    void OnDestroy()    {        network?.StopListening();    }}